        ctx.fillStyle = fhG;
        ctx.beginPath(); ctx.moveTo(96.4, 184.5); ctx.quadraticCurveTo(105.6, 182.2, 114.6, 183.8); ctx.bezierCurveTo(114.4, 191.5, 110.6, 199.5, 106, 203.5); ctx.bezierCurveTo(101.6, 199.8, 97.2, 192.2, 96.4, 184.5); ctx.fill();
